import{_ as a,o as i,c as n,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Planificación Académica: Programación II (Trimestre II-VI)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Programacion_II/Planificacion_Trimestre_II-VI.md","filePath":"materias/Programacion_II/Planificacion_Trimestre_II-VI.md"}'),s={name:"materias/Programacion_II/Planificacion_Trimestre_II-VI.md"};function o(t,e,d,l,c,u){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="planificacion-academica-programacion-ii-trimestre-ii-vi" tabindex="-1">Planificación Académica: Programación II (Trimestre II-VI) <a class="header-anchor" href="#planificacion-academica-programacion-ii-trimestre-ii-vi" aria-label="Permalink to &quot;Planificación Académica: Programación II (Trimestre II-VI)&quot;">​</a></h1><p>Este trimestre se enfoca en el dominio de las Bases de Datos y la culminación de un Proyecto Web Integral desplegado en un entorno real.</p><hr><h2 id="📅-trimestre-ii-vi-persistencia-seguridad-y-despliegue-unidades-11-a-14" tabindex="-1">📅 Trimestre II-VI: Persistencia, Seguridad y Despliegue (Unidades 11 a 14) <a class="header-anchor" href="#📅-trimestre-ii-vi-persistencia-seguridad-y-despliegue-unidades-11-a-14" aria-label="Permalink to &quot;📅 Trimestre II-VI: Persistencia, Seguridad y Despliegue (Unidades 11 a 14)&quot;">​</a></h2><p><strong>Periodo:</strong> 21/09/2026 al 28/11/2026</p><h3 id="📝-evaluacion-1-gestion-de-bases-de-datos-relacionales-unidad-11" tabindex="-1">📝 Evaluación 1: Gestión de Bases de Datos Relacionales (Unidad 11) <a class="header-anchor" href="#📝-evaluacion-1-gestion-de-bases-de-datos-relacionales-unidad-11" aria-label="Permalink to &quot;📝 Evaluación 1: Gestión de Bases de Datos Relacionales (Unidad 11)&quot;">​</a></h3><p><strong>Objetivo:</strong> Administrar la infraestructura de datos profesional para aplicaciones web.</p><ul><li><strong>Administración de Motores:</strong> Configuración de PostgreSQL/MySQL y gestión de usuarios.</li><li><strong>Esquemas y SQL:</strong> Diseño de tablas, relaciones y sentencias SQL optimizadas.</li><li><strong>Mantenimiento:</strong> Estrategias de backup y restauración de datos.</li><li><strong>Actividad:</strong> <strong>Laboratorio / Administración de Sistemas.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-integracion-backend-y-crud-sql-unidad-11" tabindex="-1">📝 Evaluación 2: Integración Backend y CRUD SQL (Unidad 11) <a class="header-anchor" href="#📝-evaluacion-2-integracion-backend-y-crud-sql-unidad-11" aria-label="Permalink to &quot;📝 Evaluación 2: Integración Backend y CRUD SQL (Unidad 11)&quot;">​</a></h3><p><strong>Objetivo:</strong> Conectar la lógica de Node.js con motores de persistencia profesionales.</p><ul><li><strong>Conectividad:</strong> Uso de drivers nativos para la comunicación Servidor-Base de Datos.</li><li><strong>Operaciones CRUD:</strong> Implementación de persistencia real para las entidades del sistema.</li><li><strong>Seguridad en Datos:</strong> Saneamiento de entradas para prevenir Inyecciones SQL.</li><li><strong>Actividad:</strong> <strong>Evaluación en Laboratorio (Desarrollo de API).</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-autenticacion-sesiones-y-seguridad-unidad-12" tabindex="-1">📝 Evaluación 3: Autenticación, Sesiones y Seguridad (Unidad 12) <a class="header-anchor" href="#📝-evaluacion-3-autenticacion-sesiones-y-seguridad-unidad-12" aria-label="Permalink to &quot;📝 Evaluación 3: Autenticación, Sesiones y Seguridad (Unidad 12)&quot;">​</a></h3><p><strong>Objetivo:</strong> Implementar la capa de seguridad lógica y control de acceso.</p><ul><li><strong>Gestión de Sesiones:</strong> Uso de Cookies y sesiones en el servidor para identificar usuarios.</li><li><strong>Autenticación:</strong> Desarrollo del flujo de Login/Registro con encriptación de datos.</li><li><strong>Protección de Rutas:</strong> Implementación de Middlewares de seguridad (ACL).</li><li><strong>Actividad:</strong> <strong>Avance de Proyecto Final.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-despliegue-real-y-defensa-final-unidades-13-y-14" tabindex="-1">📝 Evaluación 4: Despliegue Real y Defensa Final (Unidades 13 y 14) <a class="header-anchor" href="#📝-evaluacion-4-despliegue-real-y-defensa-final-unidades-13-y-14" aria-label="Permalink to &quot;📝 Evaluación 4: Despliegue Real y Defensa Final (Unidades 13 y 14)&quot;">​</a></h3><p><strong>Objetivo:</strong> Puesta en producción y validación integral del sistema.</p><ul><li><strong>Contenerización (Docker):</strong> Creación de entornos reproducibles para el sistema.</li><li><strong>Despliegue VPS:</strong> Configuración de servidores remotos, SSH y gestión con PM2.</li><li><strong>Defensa Final:</strong> Presentación del prototipo funcional desplegado en un entorno real.</li><li><strong>Actividad:</strong> <strong>Defensa Final de Carrera.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Las evaluaciones 3 y 4 conforman el <strong>Proyecto Final de Carrera</strong>, donde el alumno demuestra su capacidad para crear, asegurar y desplegar una solución web completa.</p>',20)])])}const p=a(s,[["render",o]]);export{m as __pageData,p as default};
